From 1fd0d54b095ef46df5b259c5cc4f0439a9717615 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:04:40 +0100
Subject: [PATCH] layershellv1window: configure again after a superseded
 configure

A client may ack a configure with a frame of the old size. If KWin then
went back to that size, nothing was sent and the size the client applied
next stuck. Arrange again on a size change with no configure pending.
---
 .../integration/layershellv1window_test.cpp   | 60 +++++++++++++++++++
 src/layershellv1window.cpp                    |  4 ++
 2 files changed, 64 insertions(+)

diff --git a/autotests/integration/layershellv1window_test.cpp b/autotests/integration/layershellv1window_test.cpp
index bab84bced9..39b12ba27f 100644
--- a/autotests/integration/layershellv1window_test.cpp
+++ b/autotests/integration/layershellv1window_test.cpp
@@ -56,6 +56,7 @@ private Q_SLOTS:
     void testScreenEdge_data();
     void testScreenEdge();
     void testUnconfiguredBuffer();
+    void testSupersededConfigure();
 };

 void LayerShellV1WindowTest::initTestCase()
@@ -859,6 +860,65 @@ void LayerShellV1WindowTest::testUnconfiguredBuffer()
     QVERIFY(connectionErrorSpy.wait());
 }

+void LayerShellV1WindowTest::testSupersededConfigure()
+{
+    // This test verifies that the layer surface is configured again if the client applies a
+    // configure that a later arrangement has already superseded.
+
+    // Create a panel along the left edge.
+    std::unique_ptr<KWayland::Client::Surface> surface(Test::createSurface());
+    std::unique_ptr<Test::LayerSurfaceV1> shellSurface(Test::createLayerSurfaceV1(surface.get(), QStringLiteral("dock")));
+    shellSurface->set_layer(Test::LayerShellV1::layer_top);
+    shellSurface->set_anchor(Test::LayerSurfaceV1::anchor_left | Test::LayerSurfaceV1::anchor_top | Test::LayerSurfaceV1::anchor_bottom);
+    shellSurface->set_size(100, 0);
+    shellSurface->set_exclusive_zone(100);
+    surface->commit(KWayland::Client::Surface::CommitFlag::None);
+
+    QSignalSpy configureRequestedSpy(shellSurface.get(), &Test::LayerSurfaceV1::configureRequested);
+    QVERIFY(configureRequestedSpy.wait());
+    QCOMPARE(configureRequestedSpy.last().at(1).toSize(), QSize(100, 1024));
+    shellSurface->ack_configure(configureRequestedSpy.last().at(0).toUInt());
+    Window *window = Test::renderAndWaitForShown(surface.get(), QSize(100, 1024), Qt::red);
+    QVERIFY(window);
+
+    // Create a panel along the top edge, which shortens the left panel.
+    std::unique_ptr<KWayland::Client::Surface> topSurface(Test::createSurface());
+    std::unique_ptr<Test::LayerSurfaceV1> topShellSurface(Test::createLayerSurfaceV1(topSurface.get(), QStringLiteral("dock")));
+    topShellSurface->set_layer(Test::LayerShellV1::layer_top);
+    topShellSurface->set_anchor(Test::LayerSurfaceV1::anchor_top | Test::LayerSurfaceV1::anchor_left | Test::LayerSurfaceV1::anchor_right);
+    topShellSurface->set_size(0, 50);
+    topShellSurface->set_exclusive_zone(50);
+    topSurface->commit(KWayland::Client::Surface::CommitFlag::None);
+
+    QSignalSpy topConfigureRequestedSpy(topShellSurface.get(), &Test::LayerSurfaceV1::configureRequested);
+    QVERIFY(topConfigureRequestedSpy.wait());
+    topShellSurface->ack_configure(topConfigureRequestedSpy.last().at(0).toUInt());
+    Window *topWindow = Test::renderAndWaitForShown(topSurface.get(), topConfigureRequestedSpy.last().at(1).toSize(), Qt::blue);
+    QVERIFY(topWindow);
+    QTRY_COMPARE(configureRequestedSpy.count(), 2);
+    QCOMPARE(configureRequestedSpy.last().at(1).toSize(), QSize(100, 974));
+
+    // Acknowledge the configure with a frame that still has the old size, and remove the top
+    // panel before applying the new size.
+    shellSurface->ack_configure(configureRequestedSpy.last().at(0).toUInt());
+    Test::render(surface.get(), QSize(100, 1024), Qt::red);
+    topShellSurface.reset();
+    QVERIFY(Test::waitForWindowClosed(topWindow));
+    QTRY_COMPARE(workspace()->clientArea(PlacementArea, window), RectF(100, 0, 1180, 1024));
+
+    // Applying the superseded configure should make the compositor ask for the full height again.
+    Test::render(surface.get(), QSize(100, 974), Qt::red);
+    QVERIFY(configureRequestedSpy.wait());
+    QCOMPARE(configureRequestedSpy.last().at(1).toSize(), QSize(100, 1024));
+
+    shellSurface->ack_configure(configureRequestedSpy.last().at(0).toUInt());
+    Test::render(surface.get(), QSize(100, 1024), Qt::red);
+    QTRY_COMPARE(window->frameGeometry(), RectF(0, 0, 100, 1024));
+
+    shellSurface.reset();
+    QVERIFY(Test::waitForWindowClosed(window));
+}
+
 } // namespace KWin

 WAYLANDTEST_MAIN(KWin::LayerShellV1WindowTest)
diff --git a/src/layershellv1window.cpp b/src/layershellv1window.cpp
index bee106ff1b..d556866956 100644
--- a/src/layershellv1window.cpp
+++ b/src/layershellv1window.cpp
@@ -292,6 +292,10 @@ void LayerShellV1Window::handleConfigureAcknowledged(quint32 serial)
 void LayerShellV1Window::handleSizeChanged()
 {
     updateGeometry(RectF(pos(), clientSizeToFrameSize(surface()->size())));
+    // The client may have applied a configure that a later arrangement already considered done
+    if (m_configureEvents.isEmpty()) {
+        scheduleRearrange();
+    }
 }

 void LayerShellV1Window::handleUnmapped()
