Date: Sun, 22 Nov 2026 03:28:53 +0100
Subject: [PATCH] layershellv1integration: reserve exclusive zones by priority
 first

Horizontal panels always reserved their space first, so a vertical panel
could never take the screen corners. Layer surfaces can now set a
priority with org_kde_plasma_surface, and higher ones go first.

BUG: 520053
---
 src/layershellv1integration.cpp |  9 +++++++++
 src/wayland/plasmashell.cpp     | 18 +++++++++++++++++-
 src/wayland/plasmashell.h       | 12 ++++++++++++
 src/wayland_server.cpp          |  1 +
 4 files changed, 39 insertions(+), 1 deletion(-)

diff --git a/src/layershellv1integration.cpp b/src/layershellv1integration.cpp
index 82688a6cf7..2f9250bedd 100644
--- a/src/layershellv1integration.cpp
+++ b/src/layershellv1integration.cpp
@@ -10,6 +10,7 @@
 #include "wayland/display.h"
 #include "wayland/layershell_v1.h"
 #include "wayland/output.h"
+#include "wayland/plasmashell.h"
 #include "wayland_server.h"
 #include "workspace.h"

@@ -163,6 +164,12 @@ static int weightForWindow(const LayerShellV1Window *window)
     return (window->shellSurface()->anchor() & AnchorHorizontal) == AnchorHorizontal ? 1 : 0;
 }

+static int priorityForWindow(const LayerShellV1Window *window)
+{
+    const PlasmaShellSurfaceInterface *plasmaShellSurface = PlasmaShellSurfaceInterface::get(window->surface());
+    return plasmaShellSurface ? plasmaShellSurface->exclusiveZonePriority() : 0;
+}
+
 static QList<LayerShellV1Window *> windowsForOutput(LogicalOutput *output)
 {
     QList<LayerShellV1Window *> result;
@@ -181,6 +188,8 @@ static QList<LayerShellV1Window *> windowsForOutput(LogicalOutput *output)
             return false;
         } else if (a->layer() > b->layer()) {
             return true;
+        } else if (priorityForWindow(a) != priorityForWindow(b)) {
+            return priorityForWindow(a) > priorityForWindow(b);
         } else {
             return weightForWindow(a) > weightForWindow(b);
         }
