@@ -71,6 +72,7 @@ private:
     void org_kde_plasma_surface_set_panel_takes_focus(Resource *resource, uint32_t takes_focus) override;
     void org_kde_plasma_surface_set_skip_switcher(Resource *resource, uint32_t skip) override;
     void org_kde_plasma_surface_open_under_cursor(Resource *resource) override;
+    void org_kde_plasma_surface_set_exclusive_zone_priority(Resource *resource, int32_t priority) override;
 };

 PlasmaShellInterface::PlasmaShellInterface(Display *display, QObject *parent)
@@ -278,6 +280,15 @@ void PlasmaShellSurfaceInterfacePrivate::org_kde_plasma_surface_set_panel_takes_
     Q_EMIT q->panelTakesFocusChanged();
 }

+void PlasmaShellSurfaceInterfacePrivate::org_kde_plasma_surface_set_exclusive_zone_priority(Resource *resource, int32_t priority)
+{
+    if (m_exclusiveZonePriority == priority) {
+        return;
+    }
