@@ -298,6 +309,11 @@ bool PlasmaShellSurfaceInterface::wantsOpenUnderCursor() const
     return d->m_openUnderCursorRequested;
 }

+int PlasmaShellSurfaceInterface::exclusiveZonePriority() const
+{
+    return d->m_exclusiveZonePriority;
+}
+
