From 4351b7aaec183f73b3219960f57c8285b2706090 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 03:29:11 +0100
Subject: [PATCH] plasmashellwaylandintegration: add setExclusiveZonePriority

A layer shell window had no way to ask the compositor to reserve its
exclusive zone before the others. This wraps the new plasma-shell
request, which lets a vertical panel take the screen corners.

BUG: 520053
---
 .../plasmashellwaylandintegration.cpp          | 18 +++++++++++++++++-
 .../plasmashellwaylandintegration.h            |  9 +++++++++
 2 files changed, 26 insertions(+), 1 deletion(-)

diff --git a/src/plasmaquick/plasmashellwaylandintegration.cpp b/src/plasmaquick/plasmashellwaylandintegration.cpp
index c3af1b75c..5b4d80168 100644
--- a/src/plasmaquick/plasmashellwaylandintegration.cpp
+++ b/src/plasmaquick/plasmashellwaylandintegration.cpp
@@ -19,7 +19,7 @@ class PlasmaShellManager : public QWaylandClientExtensionTemplate<PlasmaShellMan
 {
 public:
     PlasmaShellManager()
-        : QWaylandClientExtensionTemplate<PlasmaShellManager>(8)
+        : QWaylandClientExtensionTemplate<PlasmaShellManager>(9)
     {
         initialize();
     }
@@ -71,6 +71,7 @@ public:
     QtWayland::org_kde_plasma_surface::role m_role = QtWayland::org_kde_plasma_surface::role_normal;
     bool m_takesFocus = false;
     bool m_openUnderCursor = false;
+    int m_exclusiveZonePriority = 0;
     std::unique_ptr<PlasmaShellSurface> m_shellSurface;
 };

@@ -121,6 +122,9 @@ void PlasmaShellWaylandIntegrationPrivate::surfaceCreated()
         if (m_openUnderCursor) {
             m_shellSurface->open_under_cursor();
         }
+        if (m_exclusiveZonePriority != 0 && m_shellSurface->version() >= ORG_KDE_PLASMA_SURFACE_SET_EXCLUSIVE_ZONE_PRIORITY_SINCE_VERSION) {
+            m_shellSurface->set_exclusive_zone_priority(m_exclusiveZonePriority);
+        }
     }
 }

@@ -228,4 +232,16 @@ void PlasmaShellWaylandIntegration::openUnderCursor()
     }
 }

+void PlasmaShellWaylandIntegration::setExclusiveZonePriority(int priority)
+{
+    if (priority == d->m_exclusiveZonePriority) {
+        return;
+    }
+    d->m_exclusiveZonePriority = priority;
+
+    if (d->m_shellSurface && d->m_shellSurface->version() >= ORG_KDE_PLASMA_SURFACE_SET_EXCLUSIVE_ZONE_PRIORITY_SINCE_VERSION) {
+        d->m_shellSurface->set_exclusive_zone_priority(priority);
+    }
+}
+
 #include "moc_plasmashellwaylandintegration.cpp"
diff --git a/src/plasmaquick/plasmashellwaylandintegration.h b/src/plasmaquick/plasmashellwaylandintegration.h
index 99e334e86..aa6ea5b4a 100644
--- a/src/plasmaquick/plasmashellwaylandintegration.h
+++ b/src/plasmaquick/plasmashellwaylandintegration.h
@@ -68,6 +68,15 @@ public:
      */
     void openUnderCursor();

+    /*!
+     * Set the priority with which the compositor reserves the exclusive zone of this
+     * layer shell surface. Higher priorities are reserved first and take the space
+     * where exclusive zones meet, such as screen corners. The default is 0.
+     *
+     * \since 6.9
+     */
+    void setExclusiveZonePriority(int priority);
+
     bool eventFilter(QObject *watched, QEvent *event) override;

 private:
-- 
