From 313ab1603ed1b37c887c28bd8bca2ebc69ed7db3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 03:48:42 +0100
Subject: [PATCH] shell: let a vertical panel take the screen corners

Horizontal panels always took the screen corners, so a vertical panel
could never reach the top or bottom of the screen. A vertical panel that
fills its edge can now ask KWin to reserve its space before them.

BUG: 520053
---
 shell/CMakeLists.txt |  2 ++
 shell/panelview.cpp  | 56 +++++++++++++++++++++++++++++++++++++++++---
 shell/panelview.h    | 13 ++++++++++
 3 files changed, 68 insertions(+), 3 deletions(-)

diff --git a/shell/CMakeLists.txt b/shell/CMakeLists.txt
index 05393e8838..f35380f210 100644
--- a/shell/CMakeLists.txt
+++ b/shell/CMakeLists.txt
@@ -106,6 +106,8 @@ qt6_generate_wayland_protocol_client_sources(plasmashell_osd
 )

 target_sources(plasmashell PRIVATE ${plasma_shell_SRCS})
+# PanelView uses PlasmaShellWaylandIntegration, which needs the plasma-shell header generated for plasmashell_osd
+add_dependencies(plasmashell plasmashell_osd)

 target_link_libraries(plasmashell PRIVATE
  KF6::ConfigCore # Activate KRunner on the desktop
diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..4c32d48606 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -33,6 +33,7 @@

 #include <Plasma/Containment>
 #include <PlasmaQuick/AppletQuickItem>
+#include <PlasmaQuick/PlasmaShellWaylandIntegration>

 #include <LayerShellQt/Window>

@@ -400,6 +401,27 @@ void PanelView::setFloatingApplets(bool floatingApplets)
     Q_EMIT floatingAppletsChanged();
 }

+bool PanelView::coversCorners() const
+{
+    return m_coversCorners;
+}
+
+void PanelView::setCoversCorners(bool coversCorners)
+{
+    if (m_coversCorners == coversCorners) {
+        return;
+    }
+
+    m_coversCorners = coversCorners;
+    if (hasConfig()) {
+        resolutionIndependentConfig().writeEntry("coversCorners", (int)coversCorners);
+        m_corona->requestApplicationConfigSync();
+    }
+    Q_EMIT coversCornersChanged();
+
+    positionAndResizePanel();
+}
+
 int PanelView::minThickness() const
 {
     if (formFactor() == Plasma::Types::Vertical) {
@@ -632,6 +654,13 @@ void PanelView::updateLayerWindow()
     m_layerWindow->setExclusiveEdge(edge);
     m_layerWindow->setMargins(margins);

+    // KWin gives the screen corners to horizontal panels unless a panel asks to reserve its space first
+    const bool takesCorners = m_coversCorners && formFactor() == Plasma::Types::Vertical && m_lengthMode == PanelView::LengthMode::FillAvailable;
+    if (takesCorners != m_takesCorners) {
+        m_takesCorners = takesCorners;
+        PlasmaShellWaylandIntegration::get(this)->setExclusiveZonePriority(takesCorners ? 1 : 0);
+    }
+
     requestUpdate();
 }

@@ -648,7 +677,7 @@ void PanelView::positionPanel()
     updateLayerWindow();

     // TODO: should we remove this? It's still relevant on wayland because of popup positioning.
-    const QPoint pos = geometryByDistance(0).topLeft();
+    const QPoint pos = expectedPosition();
     setPosition(pos);
     updateMask();
     Q_EMIT geometryChanged();
@@ -673,7 +702,7 @@ void PanelView::positionAndResizePanel()
     }

     // TODO: can be removed? It's still relevant on wayland because of popup positioning.
-    const QPoint pos = geometryByDistance(0).topLeft();
+    const QPoint pos = expectedPosition();

     const QRect geom = {pos, sizeHint};
     bool geomChanged = geom != geometry();
@@ -769,6 +798,26 @@ QRect PanelView::geometryByDistance(int distance) const
     return r;
 }

+QPoint PanelView::expectedPosition() const
+{
+    QPoint pos = geometryByDistance(0).topLeft();
+    if (formFactor() != Plasma::Types::Horizontal || m_lengthMode != PanelView::LengthMode::FillAvailable) {
+        return pos;
+    }
+
+    // We never learn our real position, but KWin places us after a left panel that takes the screen corners
+    int offset = 0;
+    const auto containments = m_corona->containments();
+    for (Plasma::Containment *containment : containments) {
+        const PanelView *panel = m_corona->panelView(containment);
+        if (panel && panel->m_takesCorners && panel->location() == Plasma::Types::LeftEdge && panel->m_screenToFollow == m_screenToFollow) {
+            offset = std::max(offset, panel->m_layerWindow->exclusionZone());
+        }
+    }
+    pos.rx() += offset;
+    return pos;
+}
+
 QSize PanelView::preferredSize() const
 {
     if (!m_initCompleted) {
@@ -848,6 +897,7 @@ void PanelView::restore()

     setFloating((bool)resolutionIndependentConfig().readEntry<int>("floating", defaultFloating()));
     setFloatingApplets((bool)resolutionIndependentConfig().readEntry<int>("floatingApplets", false));
+    setCoversCorners((bool)resolutionIndependentConfig().readEntry<int>("coversCorners", false));
     setThickness(configDefaults().readEntry("thickness", m_configuredThickness));

     const QSize screenSize = m_screenToFollow->size();
@@ -1004,7 +1054,7 @@ void PanelView::resizeEvent(QResizeEvent *ev)
     if (m_screenToFollow && containment()) {
         updateEnabledBorders();
         // TODO: Can be removed? It's still relevant on wayland because of popup positioning.
-        const QPoint pos = geometryByDistance(0).topLeft();
+        const QPoint pos = expectedPosition();
         setPosition(pos);
         Q_EMIT m_corona->availableScreenRegionChanged(containment()->screen());

diff --git a/shell/panelview.h b/shell/panelview.h
index eb276bf7f6..1a75506761 100644
--- a/shell/panelview.h
+++ b/shell/panelview.h
@@ -141,6 +141,12 @@ class PanelView : public PlasmaQuick::ContainmentView
      */
     Q_PROPERTY(bool floatingApplets READ floatingApplets WRITE setFloatingApplets NOTIFY floatingAppletsChanged)

+    /**
+     * When this property is set to true, a vertical panel that fills its edge takes the
+     * screen corners, and horizontal panels on the same screen make room for it.
+     * @since 6.9
+     */
+    Q_PROPERTY(bool coversCorners READ coversCorners WRITE setCoversCorners NOTIFY coversCornersChanged)

 public:
     enum VisibilityMode {
@@ -200,6 +206,9 @@ public:
     bool floatingApplets() const;
     void setFloatingApplets(bool floatingApplets);

+    bool coversCorners() const;
+    void setCoversCorners(bool coversCorners);
+
     int minThickness() const;

     QRect relativeConfigRect() const;
@@ -273,6 +282,7 @@ Q_SIGNALS:
     void enabledBordersChanged();
     void floatingChanged();
     void floatingAppletsChanged();
+    void coversCornersChanged();
     void minThicknessChanged();

     void geometryChanged();
@@ -315,6 +325,7 @@ private:
     int readConfigValueWithFallBack(const QString &key, int defaultValue);
     KWindowEffects::SlideFromLocation slideLocation() const;
     void updateLayerWindow();
+    QPoint expectedPosition() const;
     void positionPanel();
     void positionAndResizePanel();
     void updateThickness();
@@ -346,6 +357,8 @@ private:
     bool m_initCompleted;
     bool m_floating;
     bool m_floatingApplets;
+    bool m_coversCorners = false;
+    bool m_takesCorners = false;
     bool m_containsMouse = false;
     bool m_containsDrag = false;
     bool m_fakeEventPending = false;
